// Command terraform-provider-thousandeyes serves the ThousandEyes provider.
//
// Most of this provider is generated by tfpluginframeworkgen from the blueprints in the
// parent repository. Files carrying a "Code generated ... DO NOT EDIT." header are
// rewritten on every generation; change the blueprint and regenerate instead.
// Registry documentation is rendered from the provider schema plus the examples/ tree.
// The examples are emit scaffolds -- generated once, then owned -- and this directive is
// what CI re-runs to prove the committed docs/ match the schema they document.
//
//go:generate go tool tfplugindocs generate --provider-name thousandeyes --rendered-provider-name ThousandEyes

package main

import (
	"context"
	"flag"
	"log"

	"github.com/hashicorp/terraform-plugin-framework/providerserver"

	"github.com/deploymenttheory/terraform-plugin-framework-codegen/pilot/thousandeyes/internal/provider"
)

// version is overridden at release time via -ldflags.
var version = "dev"

func main() {
	var debug bool
	flag.BoolVar(&debug, "debug", false, "run with support for debuggers such as delve")
	flag.Parse()

	err := providerserver.Serve(context.Background(), provider.New(version), providerserver.ServeOpts{
		Address: "registry.terraform.io/deploymenttheory/thousandeyes",
		Debug:   debug,
	})
	if err != nil {
		log.Fatalf("error: %v", err)
	}
}
